def merge_intervals(iv: list) -> list:
    if not iv:
        return []

    # Sort intervals based on start time
    iv.sort(key=lambda x: x[0])

    merged = [iv[0]]

    for current in iv[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            # Overlapping intervals, update the end time
